
import { findSimilarListings } from "./vector-similarity";

// Fictional listings and manually assigned sample vectors.
// These are NOT embeddings generated by OpenAI.
const listings = [
  {
    id: "HOME-101",
    description: "Charming craftsman home with mountain views",
    embedding: [0.95, 0.9, 0.8],
  },
  {
    id: "HOME-102",
    description: "Modern downtown apartment",
    embedding: [0.1, 0.2, 0.9],
  },
  {
    id: "HOME-103",
    description: "Cozy cottage with scenic hillside views",
    embedding: [0.85, 0.8, 0.75],
  },
  {
    id: "HOME-104",
    description: "Traditional family home with a large garden",
    embedding: [0.7, 0.6, 0.5],
  },
  {
    id: "HOME-105",
    description: "Luxury condominium near shopping",
    embedding: [0.2, 0.3, 0.85],
  },
  {
    id: "HOME-106",
    description: "Rustic mountain retreat with natural character",
    embedding: [0.9, 0.95, 0.7],
  },
];

const query =
  "Charming craftsman with mountain views and character";

// Simulated query vector, using the same illustrative dimensions.
const queryEmbedding = [1, 0.9, 0.8];

const results = findSimilarListings(
  queryEmbedding,
  listings.map((listing) => ({
    listingId: listing.id,
    embedding: listing.embedding,
  })),
  5
);

console.log("\nWEEK 6 — OFFLINE SEMANTIC SEARCH");
console.log("Query:", query);
console.log("\nTop 5 matching properties:\n");

results.forEach((result, index) => {
  const listing = listings.find(
    (item) => item.id === result.listingId
  );

  console.log(
    `${index + 1}. ${result.listingId}`
  );
  console.log(`   ${listing?.description}`);
  console.log(
    `   Similarity: ${result.score.toFixed(4)}\n`
  );
});
